/* Gerado fielmente de psiquiatria.pdf. Não editar manualmente. */
window.TRYCKTRACK_QUESTION_BANK = (window.TRYCKTRACK_QUESTION_BANK || []).concat([{"id":"psi-inep-001","number":1,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281689","stem":"Menino, 3 anos e 3 meses, é levado pela mãe para consulta na Unidade Básica de Saúde com queixa de apresentar pouco contato visual, dificuldade de interação com os colegas da creche, preferindo brincar sozinho alinhando brinquedos repetidamente, além de apresentar episódios de irritabilidade diante de mudanças na rotina. Fala apenas \"mãe\", \"pai\" e \"não\", isoladamente. A mãe nega doenças prévias importantes. Sem alterações no exame físico, neurológico ou dismorfias. A conduta mais adequada nesse caso é","options":{"A":"encaminhar para avaliação multidisciplinar em serviço especializado e iniciar intervenção precoce.","B":"explicar que algumas variações no comportamento são comuns nessa idade e programar retorno em 6 meses para reavaliação.","C":"realizar acompanhamento clínico por 4 meses e, se não houver melhora, aplicar o instrumento M-CHART-R/F.","D":"iniciar intervenção fonoaudiológica e programar reavaliação sistemática em 3 meses."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-002","number":2,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281679","stem":"Jovem de 17 anos, previamente hígido, é levado à Unidade de Pronto Atendimento após ter sido encontrado pelos pais sonolento e com sinais de ingestão de medicamentos não conhecidos. Após a estabilização clínica inicial, o paciente está consciente, mas pouco colaborativo com a equipe médica, apresenta discurso lentificado e evasivo, dizendo estar há cerca de 3 meses com humor deprimido, perda de interesse e culpa excessiva. Ele confirma a tentativa de suicídio e diz que já vinha planejando há semanas, mas pede veementemente ao médico plantonista que mantenha sigilo total sobre a tentativa de suicídio e o motivo (alega ser vítima de bullying na escola), pois tem medo da reação dos pais, que estão aguardando na sala de espera. Qual é a conduta adequada no contexto desse atendimento?","options":{"A":"Manter o sigilo sobre a tentativa de suicídio e os sintomas depressivos preservando o vínculo com o paciente, iniciar o tratamento farmacológico com um inibidor seletivo da recaptação de serotonina e solicitar parecer da psiquiatria.","B":"Quebrar o sigilo com os pais, porém informar que se trata apenas de uma intoxicação medicamentosa, iniciar o tratamento farmacológico com um inibidor seletivo da recaptação de serotonina e solicitar o parecer da psiquiatria.","C":"Quebrar o sigilo com os pais sobre a tentativa de suicídio e a real gravidade do risco, avaliar as opções de seguimento, verificando se há possibilidade de vigilância domiciliar ou necessidade de hospitalização.","D":"Manter o sigilo sobre a tentativa de suicídio e os sintomas depressivos preservando o vínculo com o paciente, iniciar a avaliação formal do risco de suicídio e providenciar o encaminhamento para internação psiquiátrica em regime compulsório."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-003","number":3,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281672","stem":"Homem de 57 anos faz uso de amitriptilina 100 mg/dia, há mais de 10 anos, para melhora do sono e diminuição da sensação de ansiedade. Sem histórico de comorbidades ou uso de outra medicação. Busca consulta médica em Unidade Básica de Saúde para avaliar riscos do uso prolongado da medicação. Quais exames complementares são indicados para o acompanhamento do uso de amitriptilina nesse paciente?","options":{"A":"Creatinina, transaminases hepáticas, potássio sérico e eletrocardiograma.","B":"Creatinina, lipidograma e TSH séricos e ultrassonografia de abdome.","C":"Transaminases hepáticas, potássio sérico, ultrassonografia de abdome e radiografia de tórax.","D":"Sódio, potássio, lipidograma e TSH séricos, eletrocardiograma e radiografia de tórax."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-004","number":4,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281651","stem":"Mulher de 38 anos, com diagnósticos de hipertensão arterial sistêmica, diabetes mellitus e transtorno afetivo bipolar, comparece à consulta médica com discurso desconexo, tremor grosseiro em extremidades e marcha atáxica, iniciada há alguns dias. Faz uso regular de captopril, metformina, carbonato de lítio e recentemente foi introduzida hidroclorotiazida devido a descontrole pressórico. Ao exame clínico, apresenta-se normocorada; desidratada (1+/4+); anictérica; afebril; PA 140 x 90 mmHg; FC 98 bpm e glicemia capilar de 95 mg/dL. Nesse contexto, qual é a medida terapêutica mais indicada para o quadro atual?","options":{"A":"Administrar carvão ativado.","B":"Suspender metformina.","C":"Administrar levodopa + carbidopa.","D":"Suspender carbonato de lítio."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-005","number":5,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281629","stem":"Mulher, 55 anos, funcionária de segurança, é levada à Unidade Básica de Saúde por sua Agente Comunitária de Saúde (ACS) devido a delírio persecutório. Segundo relatos da ACS, a paciente chegou a proferir uma clara ameaça de morte à vizinha, a quem atribuiria a realização de trabalhos espirituais contra ela. Enquanto aguardava ser chamada na recepção, a paciente começou a ficar progressivamente agitada, falando sozinha, e tentou agredir outros usuários com um cabo de vassoura. Após tentativa de abordagem verbal e posterior restrição de espaço realizada pela equipe de enfermagem, ela ficou ainda mais agitada e passou a tentar agredir todos que se aproximavam. A sequência de procedimentos adequados para esse caso é","options":{"A":"administração de haloperidol intramuscular, seguida de nova intervenção verbal.","B":"administração de diazepam intramuscular, seguida de observação em consultório.","C":"contenção mecânica, seguida de administração de haloperidol intramuscular.","D":"contenção mecânica, seguida de observação em consultório."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-006","number":6,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281622","stem":"Mulher tabagista, 38 anos, procura Unidade Básica de Saúde após recente falecimento do pai por adenocarcinoma de pulmão. Afirma que gostaria de ajuda para parar de fumar, pois falhou nas 5 vezes em que havia tentado por conta própria nos últimos anos. Relata tabagismo de 20 cigarros por dia desde os 18 anos de idade e que, nas tentativas de cessação, fez uso de \"chicletes de nicotina\", sem orientação médica. Nega uso de álcool, outras substâncias psicoativas ou medicamentos. Não apresenta queixas depressivas, ansiosas ou psicóticas. Além de encaminhar para o grupo de cessação de tabagismo, qual é o medicamento indicado como primeira linha de tratamento, segundo protocolos do Ministério da Saúde?","options":{"A":"Fluoxetina.","B":"Dissulfiram.","C":"Bupropiona.","D":"Diazepam."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-007","number":7,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281608","stem":"Puérpera, 21 anos, é acolhida Unidade Básica de Saúde, após o nascimento da filha, há dez dias. Relata que pensa em entregar a filha para a avó cuidar, uma vez que se sente “sugada” pela recém-nascida, e sente momentos de tristeza ao longo do dia, quando se questiona se deveria ter engravidado ou não, desejando interromper a amamentação, voltar a trabalhar e, principalmente, não estar com a filha. Sente-se muito culpada por pensar dessa maneira e envergonhada por não conseguir ser uma “boa mãe”. Queixa-se também do sono, pois as noites maldormidas a deixam mais irritada. Está ainda mais preocupada, pois nunca se sentiu assim. Qual é a conduta mais adequada para esse caso?","options":{"A":"Encaminhar para apoio psicossocial.","B":"Prescrever o uso de fluoxetina.","C":"Encaminhar para tratamento no CAPS.","D":"Prescrever o uso de clonazepam."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-008","number":8,"area":"Psiquiatria","source":"INEP","sourceCode":"4000281601","stem":"Mulher, 32 anos, foi internada em enfermaria de cirurgia para realização de toracotomia eletiva. No 3º dia pós-operatório, foi encontrada com alteração do nível de consciência e diversas cartelas de morfina vazias em sua bolsa. Além do rebaixamento do nível de consciência (escala de coma de Glasgow 8), a paciente apresentava pele fria e pegajosa; miose bilateral puntiforme; PA 100 x 60 mmHg; FC 56 bpm; FR 8 irpm; SatO₂ 86% em ar ambiente e temperatura axilar 36 °C. Qual medicação é indicada para reversão do quadro?","options":{"A":"Atropina.","B":"Dopamina.","C":"Flumazenil.","D":"Naloxona."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-009","number":9,"area":"Psiquiatria","source":"INEP","sourceCode":"4000282619","stem":"Mulher de 32 anos, parda, ensino fundamental incompleto, trabalhadora rural, diarista n o plantio de morango, procura Unidade Básica de Saúde (UBS) com queixas de tonturas, dores de cabeça, cansaço, náuseas e falta de ar. Ela referiu que desde os 20 anos sofre com dores de cabeça frequentes, mas há 2 semanas, após uma pulverização de agrotóxicos, começou a apresentar os sintomas descritos. Disse ainda que sua colega de trabalho apresentava queixas similares. Ao ouvir esses relatos, a médica da UBS suspeita de intoxicação aguda por agrotóxicos. Nessa situação, qual é a conduta adequada a ser adotada na assistência?","options":{"A":"Encaminhar como caso suspeito ao centro de referência em saúde do trabalhador estadual e formalizar denúncia ao Ministério Público do Trabalho.","B":"Estabelecer nexo causal entre os sintomas e os resultados de exames complementares, para confirmar diagnóstico de intoxicação por agrotóxicos, e notificar a Vigilância em Saúde municipal.","C":"Tratar os sintomas, solicitar exames complementares, notificar o caso no Sistema de Notificação de Agravos e Doenças (Sinan), conceder atestado médico e solicitar matriciamento à Vigilância em Saúde do Trabalhador.","D":"Informar não ser responsável pelo preenchimento da comunicação de acidente de trabalho (CAT), por ser atribuição exclusiva da medicina do trabalho, no centro municipal de referência em saúde do trabalhador."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-010","number":10,"area":"Psiquiatria","source":"INEP","sourceCode":"4000282618","stem":"Pais de um menino de 10 anos levam a criança para avaliação médica em Unidade Básica de Saúde (UBS). Relatam que seu filho se dá bem com a família até que não lhe seja permitido fazer algo que deseja. Quando isso ocorre, ele fica irritado, impulsivamente agressivo e agitado por várias horas. Assim que se acalma ou consegue o que quer, fica feliz e agradável novamente. Os pais entendem que o filho parece agir deliberadamente para aborrecer os outros e nunca assume a culpa por seus próprios erros ou mau comportamento. Relatam ainda que ele discute com adultos ou figuras de autoridade e em várias situações não aceita as regras de boa convivência com os familiares. Considerando o caso descrito, qual é o diagnóstico mais provável?","options":{"A":"Transtorno afetivo bipolar.","B":"Transtorno de oposição desafiante.","C":"Transtorno disruptivo da desregulação do humor.","D":"Transtorno do déficit de atenção e hiperatividade."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-011","number":11,"area":"Psiquiatria","source":"INEP","sourceCode":"4000282611","stem":"Mulher de 21 anos comparece à consulta médica em Unidade Básica de Saúde (UBS) para avaliação de amenorreia há 4 meses, sendo descartada gravidez. Paciente relata que há 10 meses iniciou dieta para perder peso, tendo emagrecido nesse período aproximadamente 3 0 kg. H á 2 dias relata desmaio durante prática de exercício físico e, por isso, realizou eletrocardiograma (ECG) que indicou alterações no segmento ST e na onda T. Paciente nega histórico de diagnóstico de transtorno mental, mora sozinha e sua família é de outra cidade. Afirma manter o padrão alimentar, pois ainda quer perder peso. Ao exame físico, apresenta palidez de mucosa e turgor cutâneo diminuído. Altura = 1,63 m; peso = 39 kg (IMC = 14,7 kg/m ); pressão arterial = 80 x 60 mmHg; frequência cardíaca = 55 bpm e frequência respiratória = 15 irpm. Qual é a conduta adequada nesse momento?","options":{"A":"Solicitar internação em enfermaria de clínica médica.","B":"Encaminhar para internação em enfermaria de saúde mental.","C":"Continuar a investigação para causas da amenorreia na UBS.","D":"Acompanhar em ambulatório do Centro de Atenção Psicossocial (CAPs)."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-012","number":12,"area":"Psiquiatria","source":"INEP","sourceCode":"4000282604","stem":"“Internações sem consentimento aumentam na Cracolândia, em meio a denúncias de agressões”. ZYLBERKAN, M.; KRUSE, T. Folha de S. Paulo, 3 jul. 2024. Notícias como esta têm se tornado frequentes em jornais brasileiros nos últimos anos. Alguns municípios têm criado leis locais próprias para as internações involuntárias que muitas vezes contradizem as leis federais sobre o tema. Sobre a internação involuntária no Brasil, é correto afirmar que","options":{"A":"a internação involuntária é determinada, de acordo com a legislação, pela Justiça.","B":"é autorizada por médico devidamente registrado no Conselho Regional de Medicina.","C":"no prazo de 15 dias, a internação deve ser comunicada ao Ministério Público Federal.","D":"o término da internação involuntária ocorrerá por solicitação do Ministério Público Municipal."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-013","number":13,"area":"Psiquiatria","source":"INEP","sourceCode":"4000282597","stem":"Mulher de 52 anos chega ao acolhimento de Unidade Básica de Saúde (UBS), muito chorosa, e relata: “Estou com dificuldade para dormir, não tenho comido direito, desde o ocorrido ... é o meu filho, sabe ... ele morreu há 3 dias ... e a dor no meu coração está muito forte, quase insuportável”. A paciente chora copiosamente e diz que sonha com uma pessoa gritando o nome de seu filho, relembrando o momento em que o tinha encontrado na rua, vítima de atropelamento. Após o primeiro acolhimento, ela fica um pouco mais calma, relatando que não pensa em se matar, que nunca tinha sido atendida por psiquiatra ou tomado medicamentos antes, mas que nesse momento precisa de muita ajuda. Diante do caso, qual a conduta adequada?","options":{"A":"Prescrever inibidor de recaptação de serotonina para alívio dos sintomas depressivos e ansiosos.","B":"Encaminhar ao Centro de Atenção Psicossocial (CAPs) para seguimento intensivo com médico psiquiatra.","C":"Encaminhar para psicologia na atenção secundária para ofertar terapia psicanalítica breve.","D":"Acompanhar longitudinalmente para observação e ofertar apoio pela equipe da UBS."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-014","number":14,"area":"Psiquiatria","source":"INEP","sourceCode":"4000258819","stem":"Menino de 3 anos é transportado pelo Serviço Móvel de Atendimento de Urgência (SAMU) para um serviço de urgência, após ter apresentado náuseas e vômitos, evoluindo para confusão mental e um episódio de convulsão, segundo os acompanhantes. Foram encontradas, nas proximidades do local onde a criança brincava, diversas cartelas abertas de ácido acetilsalicílico, do qual o avô faz uso contínuo. No momento do transporte, estava hidratado, sonolento e hiperventilando. O agente considerado eficaz para o tratamento imediato é","options":{"A":"carvão ativado.","B":"N-acetilcisteína.","C":"xarope de ipeca.","D":"atropina."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-015","number":15,"area":"Psiquiatria","source":"INEP","sourceCode":"4000258817","stem":"Homem de 43 anos, dependente de álcool há 23 anos (20 doses de aguardente/dia), teve queda da própria altura com fratura fechada de tíbia, sem traumatismo cranioencefálico. Levado ao pronto-socorro, constata-se, além da fratura, nível de consciência e atenção flutuantes, desorientação temporoespacial parcial. Glicemia capilar de 45 mg/dL. Prescreve-se imediatamente reposição de glicose e hidratação. Paciente evolui com melhora inicial do estado mental e piora nas horas seguintes, passando a apresentar confusão mental, rebaixamento do nível de consciência, alterações oculares e ataxia. Encontra-se, então, hidratado, com glicemia capilar de 90 mg/dL e eletrólitos dentro da faixa de normalidade. Para tratar o quadro atual desse paciente, a seguinte conduta medicamentosa deve ser realizada imediatamente:","options":{"A":"biperideno, solução injetável 5 mg/mL, 1 ampola intravenosa lentamente.","B":"diazepam, solução injetável 10 mg/mL, 1 ampola intravenosa lentamente.","C":"haloperidol, solução injetável 5 mg/mL, 1 ampola intramuscular em região glútea.","D":"tiamina, solução injetável 100 mg/mL, 5 ampolas diluídas em soro fisiológico durante 30 minutos."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-016","number":16,"area":"Psiquiatria","source":"INEP","sourceCode":"4000258810","stem":"Homem de 22 anos, com histórico de transtorno de ansiedade, sem tratamento medicamentoso, se dirige à Unidade de Pronto Atendimento (UPA) com queixa de dor epigástrica, palpitação, falta de ar e sensação de morte iminente. Exame físico: frequência cardíaca de 96 bpm, frequência respiratória de 2 4 irpm, pressão arterial de 120 x 80 mmHg, bulhas cardíacas e ausculta torácica sem anormalidades, ausência de tiragem intercostal, abdome sem alterações. Após exames complementares, foi descartada doença cardiovascular ou respiratória aguda, porém o paciente apresentou novo episódio semelhante. Quais fármacos podem ser prescritos na crise e a longo prazo, respectivamente?","options":{"A":"Benzodiazepínico; inibidor de recaptação de serotonina.","B":"Anti-histamínico; inibidor da monoaminoxidase.","C":"Antipsicótico atípico; antidepressivo tricíclico.","D":"Vasodilatador; antipsicótico típico."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-017","number":17,"area":"Psiquiatria","source":"INEP","sourceCode":"4000258803","stem":"Mulher de 58 anos procura Unidade Básica de Saúde (UBS) para renovar receita de diazepam 10 mg. Refere que faz uso da medicação há 25 anos e que não consegue adormecer sem ele. Inclusive, queixa-se de que a medicação vem perdendo eficácia e que sua memória está muito ruim. Nesse caso, a conduta mais adequada é","options":{"A":"renovar a receita, orientar o uso moderado do diazepam e associar melatonina","B":"reduzir gradualmente o diazepam e introduzir medicação não benzodiazepínica.","C":"suspender o uso do diazepam, não renovar a receita e orientar higiene do sono.","D":"ajustar a dosagem do diazepam para 15 mg e avaliar melhora do sono para novos ajustes."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-018","number":18,"area":"Psiquiatria","source":"INEP","sourceCode":"4000258796","stem":"Mulher de 26 anos, primípara, se dirige à Unidade Básica de Saúde (UBS) para a consulta pós-parto de 8 semanas. Marido relata que, nas últimas 6 semanas, ela está chorosa na maior parte do tempo e sem vontade de fazer as atividades rotineiras. Mesmo com suporte familiar, não consegue dormir, além de se queixar de pouca energia, redução de apetite e dificuldade em cuidar do bebê. Nega pensamentos de morte, desejo de fazer mal ao bebê ou sintomas psicóticos. Exames laboratoriais normais. Nesse momento, a conduta adequada é","options":{"A":"indicar internação em enfermaria de saúde mental.","B":"tranquilizar a paciente, pois o quadro é autolimitado.","C":"iniciar antidepressivo e programar acompanhamento.","D":"encaminhar para uma Unidade de Pronto Atendimento (UPA)."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-019","number":19,"area":"Psiquiatria","source":"INEP","sourceCode":"4000240447","stem":"Mulher de 45 anos vai à unidade básica de saúde (UBS) reportando dificuldade para reduzir o consumo de cigarros. Refere fumar 20 cigarros por dia desde os 20 anos e que já tentou interromper o uso várias vezes. Relata, ainda, irritação e ansiedade quando reduz o consumo de tabaco. Diante desse caso, o plano terapêutico adequado para essa paciente consiste em","options":{"A":"reposição de nicotina com redução gradual da dose.","B":"terapia comportamental associada à reposição de nicotina.","C":"terapia comportamental e cessação imediata do tabagismo.","D":"prescrição de benzodiazepínico e redução gradual do número de cigarros diários."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-020","number":20,"area":"Psiquiatria","source":"INEP","sourceCode":"4000240442","stem":"Homem de 44 anos é levado à sala de emergência do pronto-socorro apresentando agitação intensa, confusão mental, tremores generalizados e sudorese profusa. Ao exame físico verifica-se frequência cardíaca de 110 bpm e pressão arterial (PA) de 150 x 110 mmHg. O paciente é etilista crônico, sem antecedentes patológicos e seus familiares relatam que ele interrompeu o consumo de álcool há 48 horas. Com base nessas informações, assinale a alternativa que apresenta, respectivamente, o diagnóstico correto e a conduta inicial para esse paciente.","options":{"A":"Delirium tremens; administração de antipsicóticos, como haloperidol.","B":"Delirium tremens; administração intravenosa de benzodiazepínicos, como diazepam.","C":"Encefalopatia hipertensiva; restrição de líquidos e monitoramento estrito da função renal.","D":"Encefalopatia hipertensiva; administração de nitroprussiato de sódio para redução da PA média entre 20 e 25% nas primeiras 2 horas."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-021","number":21,"area":"Psiquiatria","source":"INEP","sourceCode":"4000240438","stem":"Um casal consulta com o médico de família e comunidade devido à preocupação da esposa com marido, que tem demonstrado compulsividade relacionada ao consumo de pornografia. Isso tem gerado discussões constantes entre eles, pois o homem é motorista por aplicativo e está deixando de trabalhar devido a este padrão de comportamento — o que tem impactado na situação financeira da família, que já é difícil. Ele relata que a prática começou como distração e alívio do estresse, mas admite que tem dificuldades para controlar esses comportamentos e reconhece as consequências que isso tem g erado para seu contexto familiar. Durante a consulta, o médico identifica sinais de baixa autoestima e de ansiedade nesse paciente. Diante desse relato, qual é o grau de motivação do paciente para a mudança de comportamento?","options":{"A":"Ação, visto que já planeja e cria condições para que uma mudança comportamental ocorra.","B":"Contemplação, visto que admite o problema e é ambivalente em relação ao seu comportamento.","C":"Pré-contemplação, visto que reconhece o impacto do vício em seu relacionamento e em sua família.","D":"Preparação, visto que sua percepção sobre os efeitos do vício ainda é limitada, sem possibilidade de mudança."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-022","number":22,"area":"Psiquiatria","source":"INEP","sourceCode":"4000240398","stem":"Criança de 6 meses e 15 dias é levada pela mãe para uma consulta de puericultura com a médica de família e comunidade devido à dificuldade de introdução alimentar, pois apresenta baixa aceitação das papas de frutas e de legumes. A mãe relata preocupação, pois o desenvolvimento da criança tem sido diferente da experiência que teve com o primeiro filho, que aceitou rapidamente as primeiras papas introduzidas aos 6 meses. A médica, então, revisa o prontuário e identifica que, em avaliações anteriores, a criança não apresentava sorriso social e não vocalizava nenhum tipo de som. Esses achados foram confirmados nesta consulta. Diante desse quadro, a conduta médica apropriada é","options":{"A":"realizar o M-CHAT (Modified Children’s Autism Test) e, se o resultado for positivo, encaminhar a criança para avaliação multidisciplinar.","B":"levar em consideração a preocupação da mãe sobre o desenvolvimento da criança e investigar fatores de risco sociofamiliares e sinais de alerta.","C":"aplicar o protocolo de observação para diagnóstico de Transtorno do Espectro Autista (TEA) a ,m de diferenciar a suspeita de autismo e de outras deficiências.","D":"encaminhar a criança ao neurologista para avaliação clínica e para a solicitação de exames de imagem, a ,m de investigar o atraso de desenvolvimento."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-023","number":23,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223941","stem":"Durante um exame admissional para motorista, um paciente é questionado sobre o uso de álcool e responde, abertamente, que se sente culpado pelo uso diário de 3 cervejas. Relata haver tentado reduzir esse consumo, sem sucesso. Nega uso de álcool pela manhã. Não relatou sentir-se aborrecido pelo que familiares, ou outras pessoas próximas a ele, possam pensar sobre seu consumo frequente de bebida alcoólica. No questionário AUDIT, esse paciente teve escore 22 de 40 pontos. Assinale a alternativa que apresenta a informação correta quanto ao diagnóstico e a abordagem adequados para esse paciente.","options":{"A":"Rastreamento negativo; orientar o paciente a reduzir o consumo para 14 cervejas por semana, sendo dispensado o tratamento farmacológico nesse caso.","B":"Rastreamento positivo; orientar o paciente sobre riscos de dirigir embriagado e oferecer naltrexona ou acamprosato para fins de tratamento farmacológico.","C":"Rastreamento positivo; orientar o paciente sobre riscos de dirigir embriagado e oferecer dissulfiram e benzodiazepínicos para fins de tratamento farmacológico.","D":"Rastreamento negativo, mas consumo excessivo; orientar o paciente sobre riscos de dirigir embriagado e oferecer naltrexona para fins de tratamento farmacológico."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-024","number":24,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223936","stem":"Uma mulher de 33 anos vai a uma consulta com um clínico geral por se sentir muito deprimida, referindo tristeza e desânimo, que começaram há 6 meses. Ela conta que é natural e procedente de São Paulo, programadora de computadores, católica não praticante, casada há 6 anos, com dois filhos, e que é sedentária. Refere sentir muita fadiga, cansaço, indisposição e sono e que ganhou 7 kg nesse período. Nega ter pensamentos de morte, de culpa ou de menos- valia. Conta, também, que recebeu diagnóstico de depressão e, por isso, usou fluoxetina durante 2 meses, até 60 mg por dia, sem apresentar melhora significativa. Por ,m, referiu ter irregularidade menstrual e constipação. Ao exame, apresenta-se hidratada, corada, afebril, sem edemas, anictérica. Seus sinais vitais estão sem alterações, exceto a frequência cardíaca que está 48 batimentos por minuto em repouso. À ausculta cardíaca, notam-se bulhas normofonéticas, sem sopros. Diante desse quadro, o principal diagnóstico diferencial a ser investigado é","options":{"A":"transtorno depressivo persistente.","B":"transtorno depressivo secundário.","C":"transtorno de somatização.","D":"síndrome de Burnout."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-025","number":25,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223922","stem":"Uma médica, ao assumir seu cargo em uma unidade básica de saúde, observa alta incidência de pacientes fumantes na comunidade. Visando obter redução importante do tabagismo nesta comunidade ela estabelece um plano de ação. Considerando as orientações do Ministério da Saúde para o tabagismo, assinale a alternativa que, apresenta a estratégia mais efetiva e viável.","options":{"A":"Implementar consultas individuais semanais para os fumantes, fornecendo orientações personalizadas.","B":"Promover campanha semanal contra o tabagismo, ofertando palestras sobre seus malefícios.","C":"Organizar grupo de apoio para cessação do tabagismo, com encontro semanal no primeiro mês.","D":"Realizar visitas domiciliares semanais para incentivar o uso de adesivo e de medicamentos."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-026","number":26,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223914","stem":"Um escolar de 8 anos é levado à consulta de rotina por sua mãe, que relata estar preocupada com o desenvolvimento de seu filho. Relata ter sido alertada pela escola que o menino tem comportamento bastante impulsivo e indisciplinado, que não demonstra interesse pelas atividades desenvolvidas em sala, que não termina as tarefas propostas e que atrapalha os demais alunos com conversas frequentes ou com brincadeiras. Ela conta que ele é, de forma geral, desatento, agitado e desmotivado. Relata que desde os 4 anos ele tem esse tipo de comportamento e que, em algumas ocasiões, ele reagiu agressivamente — mas nunca em ambiente escolar. À anamnese, percebe-se erro alimentar, com preferência por alimentos açucarados e por carboidratos e, ao exame clínico, apresenta-se na faixa de sobrepeso, segundo a curva de índice de massa corpórea, sem outras anormalidades. Considerando o quadro descrito, trata-se de um caso suspeito de","options":{"A":"transtorno opositor-desafiador, deve-se realizar uma avaliação clínica e psicossocial completa, e o diagnóstico deve se basear em sintomas de desatenção, de irritação e de impulsividade, a partir de escalas variadas.","B":"transtorno do déficit de atenção e hiperatividade, deve-se realizar uma avaliação clínica e psicossocial completa, e o diagnóstico deve se basear em sintomas indicativos de desatenção, de hiperatividade e de impulsividade, a partir de escalas validadas.","C":"transtorno opositor-desafiador, deve-se realizar uma avaliação psiquiátrica completa, e o diagnóstico deve se basear em sintomas indicativos de desobediência, de atitudes de desafio e de hostilidade contra figuras de autoridade, a partir de escalas validadas.","D":"transtorno do déficit de atenção e hiperatividade, deve-se realizar uma avaliação psiquiátrica completa, e o diagnóstico deve se basear em sintomas indicativos de desatenção, de dificuldade em aceitar regras e de irritação, a partir de escalas validadas."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-027","number":27,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223894","stem":"Uma mãe leva ao pronto-socorro sua filha de 3 anos, com quadro de gastroenterite. Durante seu relato informa que a criança vinha apresentando febre persistente e que, por isso, administrou dose elevada de antitérmico. Diante desse quadro, a médica prescreve N-acetilcisteína como antídoto para a intoxicação. Considerando a prescrição médica, assinale a alternativa que apresenta o medicamento que causou a intoxicação.","options":{"A":"Ácido acetilsalicílico.","B":"Paracetamol.","C":"Ibuprofeno.","D":"Dipirona."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-028","number":28,"area":"Psiquiatria","source":"INEP","sourceCode":"4000223877","stem":"O tabaco, em seus múltiplos usos, configura-se como a principal causa evitável de morte no Brasil e no mundo. Estima-se que o tabagismo seja a causa para cerca de 40% das mortes por câncer; de 70 a 95% das mortes devido a câncer de pulmão e 75% dos óbitos decorrentes de doença pulmonar obstrutiva crônica. Para apoiar o seu enfrentamento pode- se adotar, isoladamente ou de forma combinada, diversos tipos de abordagens. Sobre o tratamento a pessoa tabagista, é correto afirmar que","options":{"A":"esquemas de aconselhamentos de maior intensidade e de intervenções breves apresentam probabilidade semelhante de ajudar o paciente a cessar o hábito de fumar.","B":"o aconselhamento e a medicação são efetivos quando usados conjuntamente, mas ineficazes na promoção da abstinência ao tabagismo quando utilizados de forma isolada.","C":"pacientes com elevada, ou muito elevada, dependência física devem iniciar tratamento medicamentoso com a associação de terapia de reposição de nicotina a bupropiona.","D":"intervenções em grupo promovem a abstinência ao tabagismo pela interação e apoio mútuo entre os participantes e pela participação ativa do fumante e do profissional de saúde."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-029","number":29,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218454","stem":"Um gestor municipal de saúde, ao perceber um significativo aumento de tabagismo entre os adolescentes em seu município no último ano, resolveu adotar estratégias para o combate ao uso do tabaco em sua região. A partir dessas informações, assinale a opção que apresenta as estratégias prioritárias a serem adotadas para essa população.","options":{"A":"Orientação e prescrição de medicamentos aos pacientes tabagistas, para auxiliar aqueles que ainda não manifestaram o desejo de cessação.","B":"Capacitação dos profissionais de saúde acerca do tratamento para cessação do tabagismo visando o atendimento de pacientes com desejo de parar de fumar.","C":"Organização de comitês nos bairros para regulação da venda e do uso de tabaco e promoção de ações em eventos para chamar atenção aos fatores de risco do uso de fumo.","D":"Encaminhamento dos fumantes para o nível de maior densidade tecnológica, considerando o difícil controle do tabagismo e a necessidade de melhores estratégias para essa ação."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-030","number":30,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218428","stem":"Durante uma visita domiciliar, o médico de família nota que a filha de 16 anos do casal visitado aparentava ser muito menor do que o vestido que usava. O casal concorda com a observação e afirma que a filha come pouco. A adolescente relata que não apresenta qualquer problema de saúde e que apenas procura se cuidar fazendo musculação e corrida diariamente, além de seguir as dietas que estuda nas redes sociais. A mãe refere que, seguindo a dieta atual, a filha havia perdido 7 kg em 1 mês. A adolescente nega vomitar após as refeições ou quaisquer problemas, exceto o fato de não menstruar há 4 meses, negando também ser sexualmente ativa. Ao exame físico, verificam-se altura de 1,7 metros e peso de 45 kg. Observa-se ainda que o exame físico da adolescente não apresenta alterações, exceto aspecto emagrecido e palidez cutaneomucosa. Para esse caso clínico, o diagnóstico e o tratamento a serem considerados inicialmente são, respectivamente,","options":{"A":"bulimia nervosa; bupropiona.","B":"hipertireoidismo; propiltiuracil.","C":"anorexia nervosa; psicoterapia.","D":"transtorno de purgação; metoclopramida."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-031","number":31,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218423","stem":"Um homem com 40 anos, apresentando queixa de perda constante de interesse e de prazer nas atividades das quais costumava gostar, relata: “não tenho vontade sequer de sair de casa”. Afirma que isso vem se mantendo nos últimos 2 meses, de forma constante e diária, mas que piorou no último mês. Conta que seus amigos e familiares também perceberam e vêm cobrando dele uma mudança de atitude. Além disso, diz que tem se sentido mais ansioso e inquieto e que apresentou 2 “crises” súbitas, há um mês, de duração de alguns minutos, em que sentiu medo intenso, taquicardia, sufocação, tontura, sudorese e sensação de que algo ruim iria acontecer e de que iria morrer. Não relaciona as crises a fatores desencadeantes ou a situações pelas quais esteja passando. Relata que, quando teve as crises, foi a um pronto- socorro, onde foram descartadas causas orgânicas para o quadro. Refere também que apresentou perda de peso considerável no último mês, mas não sabe de quanto, tendo percebido apenas por suas roupas. Diz ainda que está sem fome e que tem tido muito sono todos os dias e se sente sempre cansado, está sem concentração e tem dificuldade de pensar. Nega etilismo, tabagismo ou uso de drogas ilícitas, negando também doenças conhecidas. Ao exame físico, o paciente apresenta-se sem alterações, assim como não mostram alterações os exames recentes de hemograma, TSH, T4 livre que ele traz. Ao exame psíquico, apresenta-se colaborativo, atenção preservada, com memória e orientação sem alterações; humor deprimido e ansioso; pensamento de forma, curso e conteúdo sem alterações, assim como juízo e crítica. Não se verificam alterações senso perceptivas, observando-se discreta agitação psicomotora. Considerando-se a situação descrita, qual é diagnóstico para o caso desse paciente?","options":{"A":"Transtorno de pânico com agorafobia.","B":"Transtorno bipolar em fase depressiva.","C":"Transtorno de ansiedade generalizada.","D":"Transtorno depressivo com ataques de pânico."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-032","number":32,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218391","stem":"Um menino com 6 anos é encaminhado à unidade de estratégia de saúde da família pela escola em que estuda, por estar apresentando dificuldades de aprendizagem. A professora havia relatado para a mãe que o menino não conseguia progredir na memorização de letras e que não associava cores e imagens às palavras como fazem as demais crianças. Orientou, portanto, a realização de uma avaliação médica, pois desconfiava de que o menino tinha um transtorno de aprendizagem. Diante disso, o médico avalia o paciente e relata as seguintes observações sobre ele: face atípica sem estigmas de doenças genéticas; e ausência de doenças prévias, de distúrbio visual ou auditivo, de histórias de condições de morbidade perinatal, de alerta do desenvolvimento neuropsicomortor, de uso de medicamentos, de convulsões e de história de meningite. Acrescenta que o ambiente familiar é com pais trabalhadores e empregados e com um irmão de 9 anos do qual não há queixas escolares. Registra, ainda, que não foram identificados riscos ambientais, como alcoolismo, uso de drogas, depressão e outros transtornos. Com base nessas informações, a conduta médica inicial adequada é encaminhar o paciente para uma","options":{"A":"avaliação psicopedagógica, a fim de identificar o transtorno de aprendizagem especifico.","B":"reavaliação junto à escola, já que não há parâmetros para avaliar transtorno de aprendizagem aos 6 anos de idade.","C":"consulta com um neuropediatra, com o objetivo de identificar doenças que possam gerar transtornos de aprendizagem.","D":"equipe de reforço pedagógico, a fim de realizar acompanhamento, uma vez que a criança não apresenta problemas aparentes."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-033","number":33,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218386","stem":"Um lactente de 9 meses, nascido a termo, é trazido pela mãe ao hospital, que relata estar preocupada com o comportamento do filho, que é diferente do comportamento dos outros dois irmãos. A mãe também relata que o menino não estende os braços para pedir colo e que tem apresentado pouco contato visual quando estimulado. A história familiar mostra um tio paterno com Transtorno de Espectro Autista. Na avaliação, o médico nota o bebê irritado, com choro persistente ao ser examinado, e registra que seu desenvolvimento motor e seu estado nutricional estão adequados para a idade. Considerando-se esse quadro clínico, a conduta médica imediata a ser adotada diante do relato da mãe é","options":{"A":"encaminhar o paciente para a neuropediatria e para um geneticista.","B":"iniciar estímulos precoces e agendar breve retorno.","C":"tranquilizar a mãe e manter o bebê em consultas de rotina de puericultura.","D":"iniciar uso de risperidona e encaminhar o paciente para uma equipe multiprofissional."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-034","number":34,"area":"Psiquiatria","source":"INEP","sourceCode":"4000218384","stem":"Um homem com 46 anos comparece à consulta acompanhado de sua esposa e solicita atestado para justificar 2 dias de ausência no trabalho. Refere que, há 2 dias, apresenta diminuição do apetite, cefaleia, fadiga, tristeza e sentimento de culpa. A esposa refere que ele ingeriu grande quantidade de bebida alcoólica numa festa e que chegou em casa sendo carregado por amigos na noite anterior ao início dos sintomas. Segundo ela, isso costuma acontecer há 1 ano, cerca de 2 vezes ao mês. Após essas situações, o paciente fica bastante entristecido, não quer sair da cama e acaba faltando ao trabalho. Entre os episódios de ingesta de bebida, o paciente trabalha, estuda e tem bom funcionamento familiar e social. Nega comorbidades e uso de medicações. Ao exame físico, não apresenta alterações. Nesse caso, ao final da consulta, o médico deve explicar ao paciente que seu quadro clínico trata-se de","options":{"A":"uso nocivo de álcool.","B":"dependência de álcool.","C":"episódio depressivo moderado.","D":"síndrome de abstinência do álcool."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-035","number":35,"area":"Psiquiatria","source":"INEP","sourceCode":"4000203384","stem":"Um menino de 6 meses e 15 dias é trazido pela mãe em consulta de puericultura na unidade básica de saúde. A criança recusa papas sólidas e aceita apenas o leite materno. Revisando consultas anteriores, o médico de família e comunidade identifica que a mãe já havia demonstrado preocupação, pois a criança ainda não apresentava sorriso social, não observava a mãe nem olhava nos seus olhos enquanto mamava, não se interessava por outras crianças, não respondia a chamados e não apresentava nenhum tipo de lalação. Por isso, a criança foi encaminhada para investigação com um otorrinolaringologista, o qual não identificou nenhum déficit auditivo. A mãe, de 39 anos, apresentou diabetes gestacional. Diante desse quadro, a conduta do médico de família deve ser","options":{"A":"manter rotina de puericultura e estimulação adequada e precoce por equipe multidisciplinar até 24 meses.","B":"rastrear transtorno do espectro autista nessa criança, para descartar essa condição, antes de referenciá-la para a atenção especializada.","C":"acompanhar o desenvolvimento da criança até os 16 meses de idade, pela ausência de sinais de alerta sugestivos de transtorno do espectro autista.","D":"referenciar a criança para atenção especializada, para acompanhamento, investigação e planejamento terapêutico em conjunto com a atenção primária."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-036","number":36,"area":"Psiquiatria","source":"INEP","sourceCode":"4000203383","stem":"Um homem de 30 anos é atendido em unidade básica de saúde com queixa de alteração no padrão do sono, alternando noites de insônia com noites de sono inquieto há 7 meses. Sente-se preocupado, com medo excessivo de adoecer ou de algo desagradável ocorrer. Seus amigos o consideram inquieto, tenso, irritado e com dificuldade de se concentrar. Ele relata que mantém suas atividades profissionais normalmente. Diante desse quadro, qual é o diagnóstico mais provável?","options":{"A":"Depressão maior.","B":"Transtorno bipolar do humor.","C":"Transtorno de ansiedade generalizada.","D":"Transtorno do deficit da atenção em adulto."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-037","number":37,"area":"Psiquiatria","source":"INEP","sourceCode":"4000203368","stem":"Um paciente de 22 anos com retardo mental moderado é trazido à unidade de pronto-atendimento por quadro de náuseas, vômitos, incontinência fecal e urinária, fasciculações musculares e sialorreia. O acompanhante, que é o avô do paciente e agricultor, refere não saber o que possa ter ocorrido com o neto, o qual estava em visita a sua propriedade rural pela segunda vez. Ele não soube afirmar se o paciente ingeriu algum dos medicamentos que o avô faz uso ou outras substâncias. Ao exame, o paciente encontra-se em regular estado geral, com pupilas mióticas, lacrimejamento excessivo e sialorreia. Apresenta frequência cardíaca de 49 batimentos por minuto; glicemia capilar de 80 mg/dL; e pressão arterial de 100 × 60 mmHg. Além disso, possui ritmo cardíaco regular em dois tempos com bulhas normofonéticas e sem sopros. Com base nessas informações, a principal hipótese diagnóstica e o tratamento imediato devem ser, respectivamente,","options":{"A":"intoxicação por diltiazem; administrar fisiostigmina.","B":"intoxicação por varfarina; administrar plasma fresco.","C":"intoxicação por salbutamol; administrar fentolamina.","D":"intoxicação por organofosforados; administrar atropina."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-038","number":38,"area":"Psiquiatria","source":"INEP","sourceCode":"4000194324","stem":"Uma paciente com 22 anos foi atendida na atenção primária, acompanhada pelos pais, que estão preocupados com sua perda de peso. Eles contam que, desde os 14 anos, ela come muito pouco e que já esteve internada para “ser alimentada”. A paciente também refere ansiedade e palpitações que estão afetando o seu dia a dia. Os pais dizem que não sabem exatamente o quanto a paciente está comendo agora, mas que ela não provoca vômitos ou abusa de medicamentos. Ao exame físico, o índice de massa corporal da paciente é 14,8 kg/m² e sua pressão arterial está normal (100 × 60 mmHg), mas ela apresenta hipotensão postural assintomática (queda de 18 mmHg na diastólica), desidratação e frequência cardíaca de 42 batimentos por minuto. Diante dessa situação, o médico deve","options":{"A":"encaminhar a paciente para avaliação em hospital terciário para possível internação hospitalar.","B":"iniciar com topiramato para melhorar o transtorno alimentar e manter acompanhamento da paciente.","C":"iniciar com amitriptilina para melhorar o transtorno de ansiedade e manter acompanhamento da paciente.","D":"encaminhar a paciente para o ambulatório de atenção terciária para avaliação quanto à colocação de sonda nasoentérica."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"psi-inep-039","number":39,"area":"Psiquiatria","source":"INEP","sourceCode":"4000194289","stem":"Um homem com 50 anos chega ao pronto-socorro após queda da própria altura e dor em pulso direito. Relata perda ponderal de 25 kg nos últimos dois anos, referindo hiporexia e má alimentação. Relata ingestão de bebidas destiladas diariamente há 10 anos, cerca de 500 a 800 ml/dia, nega tabagismo, doenças preexistentes, uso de medicamentos e de drogas ilícitas. O paciente apresenta-se em estado geral ruim, apático, alerta, orientado em espaço, pouco orientado em tempo; sua marcha é atáxica. Ao exame físico, registram-se índice de massa corporal de 18 kg/m2; frequência cardíaca de 100 batimentos por minuto; frequência respiratória de 16 incursões respiratórias por minuto; pressão arterial de 100 × 60 mmHg. Observam-se diplopia, nistagmo e estrabismo convergente bilateral, punho direito edemaciado, além de amnésia retrógrada e distorção ao relatar histórias passadas. Os resultados de seus exames de sangue apresentam: hemoglobina: 13,1 g/dL (valor de referência [VR]: 13-16); hematócrito: 38% (VR: 38-50); leucócitos: 8.890 /mL (VR: 4.000-10.000); plaquetas: 280.000/mL (VR: 150.000- 400.00); sódio: 140 mEq/L (VR: 135-145); potássio: 3,8 mg/dL (VR: 3,5-5,5); cálcio: 8,4 mg/dL (VR: 8,5–10,4); magnésio: 0,9 mg/dL (VR: 1,8-2,7); glicose: 68 mg/dL (VR: 70-99); TGO/AST: 70 U/L (VR: <40); TGP/ALT: 85 U/L (VR: < 40); vitamina B1: 15 mmol/L (VR: 60-120). No resultado da ressonância magnética plano axial T2, observam-se sinais hiperintensos na região do tecto e na substância cinzenta próxima ao aqueduto cerebral. Considerando-se esse quadro clínico e a suspeita diagnóstica da Síndrome de Wernick Korsakoh, quais seriam, respectivamente, o fator etiopatogênico dessa síndrome e a conduta terapêutica adequada para o paciente?","options":{"A":"Alcoolismo; hidratação com soro glicofisiológico a 10% + complexo B oral.","B":"Traumatismo cranioencefálico; internação na unidade de terapia intensiva (UTI).","C":"Traumatismo cranioencefálico; observação e hidratação com soro glicofisiológico a 10%.","D":"Alcoolismo; tiamina parenteral intravenosa ou intramuscular (500 mg, 2 a 3 vezes por dia, por 3 dias)."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-040","number":40,"area":"Psiquiatria","source":"INEP","sourceCode":"4000194287","stem":"Um menino com 2 anos chega para atendimento no serviço de urgência com a mãe, que conta que ele ingeriu desinfetante há menos de uma hora. Ao exame, a criança apresenta-se consciente, irritada, chorosa, normotérmica, corada e hidratada, exalando um leve odor de desinfetante pela boca. Suas conjuntivas estão claras, as pupilas, isocóricas e fotorreativas; o ritmo cardíaco é regular em 2 tempos, sem sopros. Além disso, apresenta: perfusão periférica normal; frequência cardíaca de 120 batimentos por minuto; pressão arterial de 80 × 50 mmHg; frequência respiratória de 20 incursões por minuto, eupneica; murmúrio vesicular fisiológico sem ruídos adventícios. A conduta inicial no atendimento dessa criança é","options":{"A":"usar agentes neutralizantes ou substâncias diluentes, como leite e água.","B":"fazer lavagem gástrica e utilizar carvão ativado para adsorver a substância.","C":"induzir vômito para eliminar a maior quantidade possível da substância ingerida.","D":"examinar a mucosa oral e observar por 2 a 4 horas para verificar se permanece íntegra."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-041","number":41,"area":"Psiquiatria","source":"INEP","sourceCode":"4000178620","stem":"Uma mulher de 34 anos com diagnóstico de depressão procurou a unidade de saúde da família (UBS) onde você trabalha. Com base no prontuário da paciente, você observou que ela faz acompanhamento na unidade há 10 meses com outro médico da unidade. A paciente consulta sozinha, mas chegou à unidade acompanhada da irmã, com quem ela mora e que está bastante preocupada. A paciente tem sintomas de humor deprimido, fatigabilidade e choro fácil; está em uso de 40 mg/dia de fluoxetina nos últimos 6 meses, tendo apresentado discreta melhora. Segundo a paciente, há 1 mês, aproximadamente, começou a ouvir vozes e ver alguns vultos, e tem pensado em se matar, mas sem plano. Nesse caso, qual é a conduta adequada?","options":{"A":"Continuar o atendimento na UBS e trocar o tratamento.","B":"Encaminhar a paciente para internação em hospital psiquiátrico.","C":"Solicitar internação em hospital geral e otimizar o tratamento farmacológico.","D":"Referenciar a paciente à equipe multiprofissional do Centro de Atenção Psicossocial."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-042","number":42,"area":"Psiquiatria","source":"INEP","sourceCode":"4000178615","stem":"Uma mulher de 43 anos compareceu a uma unidade de saúde da família, com queixas de estresse e ansiedade. Informa que iniciou, há 10 semanas, o tratamento com sertralina 50 mg/dia e que, nesse período, apresentou uma melhora discreta dos sintomas. Entretanto, nas últimas 4 semanas, tem tido ataques recorrentes de ansiedade intensa quando precisa sair de casa, o que tem limitado seu desempenho, inclusive para atividades do dia a dia, como ir ao supermercado e buscar os filhos no colégio. Conforme relato dela, no dia desta consulta, teve muita dificuldade para sair de casa. Nesse caso, qual é a conduta adequada?","options":{"A":"Prescrever um benzodiazepínico e encaminhar a paciente para a emergência de um hospital psiquiátrico.","B":"Manter a sertralina na dose atual e monitorar a evolução da paciente.","C":"Encaminhar a paciente para um serviço com psicoterapia estruturada e reavaliar a medicação em uso.","D":"Substituir a sertralina por fluoxetina 20 mg, clonazepam 0,5 mg e clorpromazina 25 mg."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-043","number":43,"area":"Psiquiatria","source":"INEP","sourceCode":"4000178537","stem":"Pré-escolar de três anos de idade, sexo masculino, previamente hígido, foi levado à emergência, apresentando agitação psicomotora, midríase, boca seca e rubor facial. A mãe dele informou que tinha percebido os sintomas havia uma hora, ao chegar do trabalho. O menor fica em casa com a irmã, de 10 anos, durante o período da tarde, até a mãe retornar do trabalho. Conforme o quadro clínico apresentado, trata-se de intoxicação por","options":{"A":"dipirona.","B":"salbutamol.","C":"clorpromazina.","D":"dexclorfeniramina."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"psi-inep-044","number":44,"area":"Psiquiatria","source":"INEP","sourceCode":"4000178532","stem":"Pré-escolar de 3 anos e 4 meses de idade deu entrada no pronto-socorro apresentando rigidez e espasmos musculares e hipertermia. Não apresentava dificuldade respiratória. Ausculta cardíaca sem anormalidades. Sem história prévia de doença cardíaca. O paciente estava recebendo oxigenoterapia quando um primo dele, de quatro anos, deu entrada no mesmo hospital, com quadro semelhante. Ambos haviam passado as últimas 12 horas na casa da avó materna, que há anos faz tratamento de esquizofrenia e hipertensão arterial. As evidências clínicas dessa história induzem a necessidade de o médico investigar","options":{"A":"cardiopatia congênita cianótica.","B":"intoxicação exógena por captopril.","C":"intoxicação exógena de haloperidol.","D":"ingestão exógena por benzodiazepínico."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-045","number":45,"area":"Psiquiatria","source":"INEP","sourceCode":"4000176680","stem":"Uma médica da Estratégia de Saúde da Família percebeu que, nas consultas de Puericultura, houve um aumento das queixas de agitação, irritabilidade e tristeza nas crianças, durante o período da pandemia da COVID-19. Muitos genitores, preocupados com as mudanças comportamentais d o s filhos, estão solicitando a prescrição de medicamentos e encaminhamentos para consulta com Psicólogos. Nesse cenário, atenta à situação, a médica, em conjunto com a equipe de saúde, deve planejar e executar ações de saúde no território que contemplem esse novo momento. Considerando as informações apresentadas e com base na Educação Popular em Saúde, a principal ação a ser realizada com as famílias dessas crianças é a","options":{"A":"promoção de reuniões com profissionais do Centro de Atenção Psicossocial infantil e familiares para esclarecer o manejo medicamentoso dos casos.","B":"escuta ativa das queixas trazidas pelos familiares, para a compreensão do problema e construção dialogada da solução.","C":"utilização pelos profissionais da Unidade Básica de Saúde de uma série de técnicas de convencimento dos familiares para evitar a medicalização do sofrimento das crianças.","D":"elaboração de uma série de palestras informativas, com exposição das melhores evidências científicas para o tratamento das doenças neurodegenerativas da infância."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"psi-inep-046","number":46,"area":"Psiquiatria","source":"INEP","sourceCode":"4000176675","stem":"Uma mulher com 30 anos de idade vem a primeira consulta na Unidade Básica de Saúde queixando-se de tonturas, tremores, tensão muscular e relata que há 1 mês apresentou três crises de palpitações repentinas, acompanhadas de dor em hemitórax esquerdo, com duração de até meia hora e resolução espontânea. Nega doenças pregressas, tabagismo, etilismo ou uso de outras drogas. Relata que procurou serviços de emergência três vezes achando que teria um infarto. Traz resultados recentes e normais de hemograma, TSH, perfil lipídico completo, glicemia, troponina e CPK e eletrocardiograma. Acredita que esses exames foram insuficientes e pede outros exames para ver se o coração está bem. Por exercer a prostituição desde a adolescência, faz exames rotineiramente para infecções sexualmente transmissíveis, últimos há 15 dias e com resultados negativos. Usa Dispositivo Intrauterino (DIU) de cobre há 5 anos e preservativo. Não teve filhos ou abortamento. Apresenta sono reparador, exceto quando tem as crises. Nega ideação suicida. Desde o início da pandemia da COVID-19 não faz mais programas. Exame físico inalterado. Nesse caso, a melhor abordagem é","options":{"A":"referenciar a paciente ao serviço de urgência e emergência para realização de novos eletrocardiogramas (ECG) e enzimas cardíacas e solicitar avaliação de especialistas focais.","B":"solicitar novos exames para descartar outras doenças orgânicas de base e iniciar tratamento farmacológico com betabloqueador e benzodiazepínico.","C":"explicar que novos exames são desnecessários, indicar atividades físicas, apoio psicológico e retorno, em um continuum de complexidade de tratamento.","D":"explicar que novos exames são desnecessários, iniciar benzodiazepínico nas crises e antidepressivo tricíclico; indicar apoio psicológico e retorno em 6 semanas."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"psi-inep-047","number":47,"area":"Psiquiatria","source":"INEP","sourceCode":"4000176590","stem":"Um homem com 48 anos de idade é obeso, tabagista e hipertenso há 6 anos, quando, devido a esse quadro, foi-lhe recomendada mudança do estilo de vida e prescrita farmacoterapia. Procura hoje a Unidade Básica de Saúde (UBS) com níveis tensionais elevados, glicemia alterada e referindo ter deixado de usar os medicamentos anti-hipertensivos prescritos dizendo \"eles estão me fazendo sentir doente\". O paciente relata que, durante a pandemia da COVID-19, deixou de seguir as orientações alimentares, de atividade física e de cessação do tabagismo. Para esse caso, a conduta a ser adotada pela equipe da UBS é","options":{"A":"construir um projeto terapêutico singular e pactuar com o paciente as propostas de ações para a mudança do estilo de vida e a adesão medicamentosa.","B":"esclarecer o paciente, no projeto terapêutico singular, sobre as consequências da não adesão ao tratamento, destacando o perigo dos potenciais danos clínicos e reiterando firmemente o aconselhamento.","C":"utilizar, no projeto terapêutico singular, a negação do paciente aos problemas apresentados e a adesão ao tratamento como formas de pressão para obtenção da mudança do estilo de vida.","D":"condicionar, na construção do projeto terapêutico singular, a adesão às mudança do estilo de vida e ao tratamento farmacológico e comunicar ao paciente que, se não seguir as orientações da equipe, não poderá mais ser atendido na UBS."},"answer":"A","explanation":"","needsVisualReview":false}]);
